<?php $title='Suscripción'; require __DIR__.'/partials/top.php';$owner=isPlatformOwner();$plans=[];$tenants=[];try{$plans=appDb()->query('SELECT * FROM subscription_plans ORDER BY active DESC,monthly_price,name')->fetchAll();if($owner){$tenants=appDb()->query("SELECT t.id,t.name,t.status,ts.plan_id,ts.status subscription_status,sp.name plan_name FROM tenants t LEFT JOIN tenant_subscriptions ts ON ts.tenant_id=t.id LEFT JOIN subscription_plans sp ON sp.id=ts.plan_id ORDER BY t.name")->fetchAll();}}catch(Throwable $e){} ?>
<section class="welcome compact-welcome"><div><small>CONTROL COMERCIAL</small><h1>Suscripciones</h1><p><?= $owner?'Crea y administra los planes disponibles para las empresas.':'Consulta el plan contratado por tu empresa.'?></p></div><?php if($owner):?><button class="primary" data-open="planModal"><i class="fa-solid fa-plus"></i> Crear plan</button><?php endif?></section>
<section class="panel billing-panel"><div class="panel-head"><div><b>Planes disponibles</b><small><?=count($plans)?> plan(es) configurados.</small></div></div><div class="plan-grid"><?php if(!$plans):?><div class="empty-compact"><i class="fa-solid fa-layer-group"></i><b>Aún no hay planes</b><span>Usa “Crear plan” para registrar el primero.</span></div><?php else: foreach($plans as $p): $f=json_decode($p['features_json']??'[]',true)?:[];?><article class="plan-card"><div class="plan-card-head"><div><b><?=htmlspecialchars($p['name'])?></b><small><?=$p['active']?'Activo':'Inactivo'?></small></div><span class="plan-price"><?=htmlspecialchars($p['currency'])?> <?=number_format((float)$p['monthly_price'],2)?><small>/mes</small></span></div><div class="plan-limits"><span><i class="fa-solid fa-users"></i> <?=$p['max_users']?:'Ilimitados'?> usuarios</span><span><i class="fa-solid fa-comments"></i> <?=$p['max_channels']?:'Ilimitados'?> canales</span></div><?php if($f):?><div class="plan-features"><?php foreach($f as $x):?><span><i class="fa-solid fa-check"></i> <?=htmlspecialchars($x)?></span><?php endforeach?></div><?php endif?><?php if($owner):?><div class="plan-actions"><button class="soft plan-edit" data-plan='<?=htmlspecialchars(json_encode($p),ENT_QUOTES)?>'><i class="fa-solid fa-pen"></i> Editar</button><button class="soft danger plan-delete" data-id="<?=$p['id']?>" data-name="<?=htmlspecialchars($p['name'])?>"><i class="fa-solid fa-trash"></i> Eliminar</button></div><?php endif?></article><?php endforeach;endif?></div></section>
<?php if($owner):?><section class="panel billing-panel billing-assignment-panel"><div class="panel-head"><div><b>Asignación de planes por empresa</b><small>El plan define los límites reales de usuarios, canales y acceso API.</small></div></div><div class="tenant-plan-list"><?php foreach($tenants as $t):?><article class="tenant-plan-row"><div class="tenant-company-summary"><span class="tenant-company-icon"><i class="fa-solid fa-building"></i></span><div class="tenant-company-copy"><b><?=htmlspecialchars($t['name'])?></b><div class="tenant-company-meta"><span>Empresa: <?=htmlspecialchars(ucfirst((string)$t['status']))?></span><span class="dot"></span><span>Plan actual: <?=htmlspecialchars($t['plan_name']??'Sin asignar')?></span></div></div></div><form class="subscriptionAssignForm inline-form billing-assign-form"><input type="hidden" name="action" value="subscription_assign"><input type="hidden" name="tenant_id" value="<?=$t['id']?>"><div class="billing-control"><label>Plan</label><select name="plan_id" class="select2" required><option value="">Selecciona plan</option><?php foreach($plans as $p):if(!$p['active'])continue;?><option value="<?=$p['id']?>" <?=((int)($t['plan_id']??0)===(int)$p['id'])?'selected':''?>><?=htmlspecialchars($p['name'])?></option><?php endforeach?></select></div><div class="billing-control billing-status-control"><label>Estado</label><select name="status" class="select2"><option value="active" <?=($t['subscription_status']??'active')==='active'?'selected':''?>>Activo</option><option value="grace" <?=($t['subscription_status']??'')==='grace'?'selected':''?>>Gracia</option><option value="suspended" <?=($t['subscription_status']??'')==='suspended'?'selected':''?>>Suspendido</option><option value="cancelled" <?=($t['subscription_status']??'')==='cancelled'?'selected':''?>>Cancelado</option></select></div><button class="primary billing-assign-button"><i class="fa-solid fa-user-shield"></i> Asignar</button></form></article><?php endforeach?></div></section><?php endif?>
<?php if($owner):?><div class="modal-shell" id="planModal"><div class="modal-card small-modal"><div class="modal-head"><div><b id="planTitle">Crear plan</b><small>Define precio, límites y funcionalidades.</small></div><button class="modal-close"><i class="fa-solid fa-xmark"></i></button></div><form id="planForm"><input type="hidden" name="action" value="plan_save"><input type="hidden" name="plan_id"><div class="settings-grid"><div class="field full"><label>Nombre del plan</label><input name="name" required placeholder="Ej. Business"></div><div class="field"><label>Precio mensual</label><input name="monthly_price" type="number" min="0" step="0.01" required></div><div class="field"><label>Moneda</label><select name="currency" class="select2"><option>HNL</option><option>USD</option></select></div><div class="field"><label>Máximo de usuarios</label><input name="max_users" type="number" min="0" placeholder="0 = ilimitado"></div><div class="field"><label>Máximo de canales</label><input name="max_channels" type="number" min="0" placeholder="0 = ilimitado"></div><div class="field full"><label>Funcionalidades</label><textarea name="features" placeholder="Una funcionalidad por línea"></textarea><small class="field-help">Cada línea aparecerá como una característica incluida en el plan.</small></div><div class="field full plan-status-field"><label>Estado del plan</label><label class="switch-line plan-active-switch"><input type="checkbox" name="active" checked><span aria-hidden="true"></span><span class="plan-active-copy"><b>Plan activo</b><small>Disponible para asignarlo a empresas.</small></span></label><small class="field-help">Desactívalo únicamente cuando este plan ya no deba poder asignarse a nuevas empresas.</small></div></div><div class="modal-actions"><button type="button" class="soft modal-close"><i class="fa-solid fa-xmark"></i> Cancelar</button><button class="primary"><i class="fa-solid fa-floppy-disk"></i> Guardar plan</button></div></form></div></div><?php endif?>
<?php require __DIR__.'/partials/bottom.php'; ?>
